<?php require_once __DIR__.'/config/db.php';require_once __DIR__.'/includes/functions.php';$cart=$_SESSION['cart']??[];$items=[];$total=0;$ids=array_filter(array_map('intval',array_keys($cart)));if($ids){$s=$pdo->prepare('SELECT id,name,base_price,stock_quantity FROM products WHERE id IN ('.implode(',',array_fill(0,count($ids),'?')).')');$s->execute(array_values($ids));foreach($s->fetchAll() as $p){$p['quantity']=min((int)$cart[$p['id']],(int)$p['stock_quantity']);if($p['quantity']>0){$items[]=$p;$total+=$p['quantity']*$p['base_price'];}}}$errors=[];$complete=isset($_GET['complete'],$_SESSION['last_order']);if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$address=trim((string)($_POST['address']??''));$payment=(string)($_POST['payment']??'');if(!$items)$errors[]='Your bag is empty.';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$address==='')$errors[]='Enter your name, valid email, and address.';if(!in_array($payment,['Mock Card','Cash on Delivery'],true))$errors[]='Choose a payment option.';if(!$errors){try{$pdo->beginTransaction();foreach($items as $p){$l=$pdo->prepare('SELECT stock_quantity FROM products WHERE id=? FOR UPDATE');$l->execute([$p['id']]);if((int)$l->fetchColumn()<$p['quantity'])throw new RuntimeException('Stock changed; return to your bag.');}$code='DEMO-'.strtoupper(bin2hex(random_bytes(4)));$s=$pdo->prepare("INSERT INTO orders(order_code,total_amount,order_status,shipping_address,payment_method) VALUES(?,?,'Pending',?,?)");$s->execute([$code,$total,$name."\n".$email."\n".$address,$payment]);$oid=(int)$pdo->lastInsertId();$line=$pdo->prepare('INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)');$upd=$pdo->prepare('UPDATE products SET stock_quantity=stock_quantity-? WHERE id=?');foreach($items as $p){$line->execute([$oid,$p['id'],$p['quantity'],$p['base_price']]);$upd->execute([$p['quantity'],$p['id']]);}$pdo->commit();$_SESSION['cart']=[];$_SESSION['last_order']=$code;header('Location: checkout.php?complete=1');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Could not save demo order.';error_log($e->getMessage());}}}$pageTitle='Checkout';require __DIR__.'/includes/header.php'; ?>
<div class="container section-space" style="max-width:760px"><?php if($complete): ?><div class="panel text-center p-5"><h1 class="h2">Demo order recorded!</h1><p>Reference: <b><?=e($_SESSION['last_order'])?></b></p><p class="small text-secondary">No payment was processed.</p><a href="shop.php" class="btn btn-dark rounded-pill">Back to shop</a></div><?php elseif(!$items): ?><div class="panel text-center p-5"><h1 class="h4">Your bag is empty</h1><a href="shop.php" class="btn btn-dark rounded-pill mt-3">Browse products</a></div><?php else: ?><h1 class="display-6 mb-4">Demo checkout</h1><?php foreach($errors as $er): ?><div class="alert alert-danger"><?=e($er)?></div><?php endforeach; ?><form method="post" class="panel"><input type="hidden" name="csrf" value="<?=e(token())?>"><h2 class="h5">Shipping details</h2><label class="form-label mt-3" for="name">Full name</label><input class="form-control" id="name" name="name" required><label class="form-label mt-3" for="email">Email</label><input class="form-control" id="email" name="email" type="email" required><label class="form-label mt-3" for="address">Address</label><textarea class="form-control" id="address" name="address" required rows="3"></textarea><h2 class="h5 mt-4">Demo payment method</h2><select class="form-select mt-2" name="payment"><option>Mock Card</option><option>Cash on Delivery</option></select><div class="alert alert-warning small mt-4">Local testing only. No card details are collected and no real payment is made.</div><div class="d-flex justify-content-between mb-3"><span>Total</span><b><?=money($total)?></b></div><button class="btn btn-dark rounded-pill">Place demo order</button></form><?php endif; ?></div><?php require __DIR__.'/includes/footer.php'; ?>